window.registerChapter({"num": 109, "title": "Pertussis (Whooping Cough)", "group": "Bacterial infections", "pdf_start": 681, "pdf_end": 692, "printed_start": 667, "printed_end": 678, "features": ["Fever", "Conjunctivitis", "Cough", "Pneumonia", "Vomiting", "Encephalitis / seizures"], "pillars": [{"label": "Etiology and transmission", "text": "Pertussis is caused by a fastidious, gram-negative, pleomorphic bacillus, Bordetella pertussis. Other Bordetella species can cause sporadic prolonged cough illness in people, including Bordetella parapertussis, Bordetella bronchiseptica (the cause of canine kennel cough), and Bordetella holmesii.", "pdf_page": 681, "printed_page": 667}, {"label": "Clinical recognition", "text": "Pertussis begins with mild upper respiratory tract symptoms similar to the common cold (catarrhal stage) and progresses to cough, usually paroxysms of cough (paroxysmal stage), characterized by inspiratory whoop (gasping) after repeated cough on the same breath, which commonly is followed by post-tussive emesis. Symptoms wane gradually over weeks to months (convalescent stage).", "pdf_page": 681, "printed_page": 667}, {"label": "Diagnostic workup", "text": "Culture previously was considered the gold standard for laboratory diagnosis of pertussis but is not optimally sensitive and has largely been replaced by nucleic acid amplification tests (NAATs). Culture requires collection of an appropriate nasopharyngeal swab specimen, obtained either by aspiration or with polyester or flocked rayon swabs.", "pdf_page": 681, "printed_page": 667}, {"label": "Treatment in the atlas", "text": "Antimicrobial therapy administered during the catarrhal stage may ameliorate the disease. Antimicrobial therapy is indicated before test results are received if the clinical history is strongly suggestive of pertussis or the patient is at high risk of severe or complicated disease (eg, an infant).", "pdf_page": 682, "printed_page": 668}, {"label": "Prevention and infection control", "text": "In addition to standard precautions, droplet precautions are recommended for 21 days from onset of cough if appropriate antimicrobial therapy is not administered or for 5 days after initiation of effective therapy.", "pdf_page": 683, "printed_page": 669}], "figures": [{"path": "figures/ch109_p0690_01.jpg", "caption": "Image 109.1 A preschool-aged boy with pertussis. Thick respiratory secretions were produced by a paroxysmal coughing spell. Courtesy of Edgar O. Ledbetter, MD, FAAP.", "caption_matched": true, "pdf_page": 690, "printed_page": 676, "chapter": 109}, {"path": "figures/ch109_p0690_02.jpg", "caption": "Image 109.2 Bilateral subconjunctival hemorrhages and thick nasal mucus in an infant with pertussis.", "caption_matched": true, "pdf_page": 690, "printed_page": 676, "chapter": 109}, {"path": "figures/ch109_p0690_03.jpg", "caption": "Image 109.3 Radiographs obtained in a 4-week-old with pertussis pneumonia with pulmonary air trapping and progressive atelectasis confirmed at autopsy. The neonate acquired the infection from the mother shortly after birth. Segmented and lobar atelectasis are not uncommon complications of pertussis.", "caption_matched": true, "pdf_page": 690, "printed_page": 676, "chapter": 109}, {"path": "figures/ch109_p0691_01.jpg", "caption": "Image 109.5 Plugging and alveolar dilatation of pertussis pneumonia in an infant who died. Courtesy of Edgar O. Ledbetter, MD, FAAP.", "caption_matched": true, "pdf_page": 691, "printed_page": 677, "chapter": 109}, {"path": "figures/ch109_p0691_02.jpg", "caption": "Image 109.6 Pertussis pneumonia with hyperaeration (air trapping) caused by inability to cough out thick pulmonary secretions.", "caption_matched": true, "pdf_page": 691, "printed_page": 677, "chapter": 109}, {"path": "figures/ch109_p0691_03.jpg", "caption": "Image 109.7 Pertussis pneumonia in a 7-year-old who was exhausted from persistent coughing. Obliteration of cardiac borders on the chest radiograph is a common radiographic change of pertussis pneumonia.", "caption_matched": true, "pdf_page": 691, "printed_page": 677, "chapter": 109}, {"path": "figures/ch109_p0691_04.jpg", "caption": "Image 109.4 Bronchiolar plugging in the neonate in Image 109.3, who died of pertussis pneumonia. Neonates, infants, and children often acquire pertussis from an infected adult or sibling contact.", "caption_matched": true, "pdf_page": 691, "printed_page": 677, "chapter": 109}, {"path": "figures/ch109_p0692_01.jpg", "caption": "Image 109.8 This image depicts an infant girl who presented to a clinic with malnutrition as well as what was diagnosed as pertussis. Pertussis is a highly communicable, vaccinepreventable disease caused by Bordetella pertussis, a gram-negative coccobacillus, that lasts for many weeks and typically affects children with severe coughing, whooping, and post-tussive vomiting. Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 692, "printed_page": 678, "chapter": 109}, {"path": "figures/ch109_p0692_02.jpg", "caption": "Image 109.9 This child has pertussis (whooping cough). He has severe coughing spasms, which are often followed by a whooping sound. It is difficult for him to stop coughing and catch his breath. Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 692, "printed_page": 678, "chapter": 109}, {"path": "figures/ch109_p0692_03.jpg", "caption": "Image 109.11 Colonies of Bordetella pertussis growing on Bordet-Gengou media. Courtesy of Edgar O. Ledbetter, MD, FAAP.", "caption_matched": true, "pdf_page": 692, "printed_page": 678, "chapter": 109}, {"path": "figures/ch109_p0692_04.jpg", "caption": "Image 109.10 This child has broken blood vessels in his eyes and bruising on his face because of coughing from pertussis. Courtesy of Thomas Schlenker, MD, MPH, chief medical officer, Children’s Hospital of Wisconsin.", "caption_matched": true, "pdf_page": 692, "printed_page": 678, "chapter": 109}], "tables": [{"pdf_page": 683, "printed_page": 669, "markdown": "|Age|Recommended Drugs|Col3|Col4|Alternative|\n|---|---|---|---|---|\n|**Age**|**Azithromycin**|**Erythromycin**|**Clarithromycin**|**TMP-SMX**|\n|Younger than 1 mo|10 mg/kg/day as a<br>single dose daily for<br>5 daysb,c|40 mg/kg/day in<br>4 divided doses for<br>14 days|Not recommended|Contraindicated at<br>younger than 2 mo|\n|1 through 5 mo|10 mg/kg/day as a<br>single dose daily for<br>5 daysb|40 mg/kg/day in<br>4 divided doses for<br>14 days|15 mg/kg/day in<br>2 divided doses for<br>7 days|2 mo or older: TMP,<br>8 mg/kg/day; SMX,<br>40 mg/kg/day in<br>2 doses for 14 days|\n|6 mo or older and<br>children|10 mg/kg as a single<br>dose on day 1 (maxi-<br>mum 500 mg), then<br>5 mg/kg/day as a<br>single dose on days<br>2 through 5 (maxi-<br>mum 250 mg/day)b,d|40 mg/kg/day in<br>4 divided doses for<br>7–14 days (maximum<br>2 g/day)|15 mg/kg/day in<br>2 divided doses for<br>7 days (maximum<br>1 g/day)|2 mo or older: TMP,<br>8 mg/kg/day; SMX,<br>40 mg/kg/day in<br>2 doses for 14 days|\n|Adolescents and<br>adults|500 mg as a single<br>dose on day 1, then<br>250 mg as a single<br>dose on days 2<br>through 5b,d|2 g/day in 4 divided<br>doses for 7–14 days|1 g/day in 2 divided<br>doses for 7 days|TMP, 320 mg/day;<br>SMX, 1,600 mg/day<br>in 2 divided doses<br>for 14 days|\n\n", "path": "tables/ch109_p0683_1.jpg", "orientation_normalized": false}, {"pdf_page": 684, "printed_page": 670, "markdown": "|Pharmaceutical|Manufacturer|Recommended Use|\n|---|---|---|\n|DTaP (Infanrix)|GlaxoSmithKline<br>Biologicals|**All 5 doses,** children 6 wk through 6 y of age.|\n|DTaP(Daptacel)|Sanof Pasteur|**All 5 doses,** children 6 wk through 6y of age.|\n|DTaP-hepatitis B-IPV<br>(Pediarix)|GlaxoSmithKline<br>Biologicals|**First 3 doses, children 6 wk through 6 y of age; usual**<br>**use** at 2, 4, and 6 months of age; then 2 doses of DTaP are<br>needed to complete the 5-dose series before 7y of age.|\n|DTaP-IPV/Hib<br>(Pentacel)|Sanof Pasteur|**First 4 doses, children 6 wk through 4 y of age; usual**<br>**use** at 2, 4, 6, and 15 through 18 mo of age; then 1 dose of<br>DTaP is needed to complete the 5-dose series before 7y of age.|\n|DTaP-IPV-hepatitis<br>B-Hib (Vaxelis)|Merck/Sanof Pasteur|**First 3 doses, children 6 wk through 4 y of age: usual**<br>**use** at 2, 4, and 6 months of age; then 2 doses of DTaP are<br>needed to complete the 5-dose series before 7y of age.|\n|DTaP-IPV (Kinrix)|GlaxoSmithKline<br>Biologicals|**Booster dose** for**ffth dose** of DTaP and**fourth dose** of<br>IPV at 4 through 6y of age.|\n|DTaP-IPV (Quadracel)|Sanof Pasteur|**Booster dose** for**ffth dose** of DTaP and**fourth dose** of<br>IPV at 4 through 6y of age.|\n|Tdap (Boostrix)|GlaxoSmithKline<br>Biologicals|**Single dose** at 11 y or older. Can be used in place of Td.<br>One dose recommended during EACH pregnancy, optimally<br>between 27 and 36 weeks’gestation.|\n|Tdap (Adacel)|Sanof Pasteur|**Single dose** at 11 y or older. Can be used in place of Td.<br>One dose recommended during EACH pregnancy, optimally<br>between 27 and 36 weeks’gestation.|\n\n", "path": "tables/ch109_p0684_1.jpg", "orientation_normalized": false}], "reader_html": "<section><h2>Clinical Manifestations</h2><p>Pertussis begins with mild upper respiratory tract symptoms similar to the common cold (catarrhal stage) and progresses to cough, usually paroxysms of cough (paroxysmal stage), characterized by inspiratory whoop (gasping) after repeated cough on the same breath, which commonly is followed by post-tussive emesis. Fever is absent or minimal. Symptoms wane gradually over weeks to months (convalescent stage). Cough illness in immunized children and adults can range from typical to very mild. The duration of classic pertussis is 6 to 10 weeks. Complications among adolescents and adults include syncope, weight loss, sleep disturbance, incontinence, rib fractures, and pneumonia; among adults, complications may increase with age. Pertussis is most severe when it occurs during the first 6 months of life, particularly in preterm and unimmunized infants. Disease in infants younger than 6 months can be atypical with a short catarrhal stage, followed by gagging, gasping, bradycardia, or apnea as prominent early manifestations; absence of whoop; and prolonged convalescence. Complications among infants include pneumonia, pulmonary hypertension, and severe coughing spells with associated conjunctival hemorrhage, hernia, and hypoxia. Seizures (0.9%), encephalopathy (less than 0.5%), apnea, acute respiratory distress syndrome, and death can occur in infants with pertussis. Approximately a third of infants with pertussis in the United States are hospitalized. Case fatality rates are approximately 1.1% in infants younger than 2 months and 0.1% in infants 2 through 11 months of age. Immunization with tetanus and diphtheria toxoids and acellular pertussis vaccine (Tdap) during each pregnancy and an infant’s receipt of at least some doses of pertussis vaccine reduce morbidity and mortality in young infants.</p><small class='source'>Printed p. 667 · PDF p. 681</small></section><section><h2>Etiology</h2><p>Pertussis is caused by a fastidious, gram-negative, pleomorphic bacillus, Bordetella pertussis. Other Bordetella species can cause sporadic prolonged cough illness in people, including Bordetella parapertussis, Bordetella bronchiseptica (the cause of canine kennel cough), and Bordetella holmesii.</p><small class='source'>Printed p. 667 · PDF p. 681</small></section><section><h2>Epidemiology</h2><p>Humans are the only known hosts of B pertussis. Transmission occurs by close contact with infected individuals via large respiratory droplets generated by coughing or sneezing. Cases occur year-round, typically with a late summer-autumn peak. Neither infection nor immunization provides lifelong immunity. Waning immunity is predominantly responsible for increased cases reported in school-aged children, adolescents, and adults. Additionally, waning immunity in pregnant people who have not received Tdap vaccine during that pregnancy results in low concentrations of transplacentally transmitted antibody and an increased risk of pertussis in very young infants. Reported incidence is cyclic and had been increasing since the early 1990s until the start of the COVID-19 pandemic in 2020. Pertussis is highly contagious. As many as 80% of susceptible household contacts of symptomatic infant cases are infected with B pertussis, with symptoms in these contacts varying from mild to classic pertussis. Siblings and adults with cough illness are important sources of pertussis infection for young infants. Infected people are most contagious during the catarrhal stage through the third week after onset of paroxysms or until 5 days after the start of effective antimicrobial treatment. Factors affecting the length of communicability include age, immunization status or previous infection, and receipt of appropriate antimicrobial therapy.</p><small class='source'>Printed p. 667 · PDF p. 681</small><p>The incubation period is 7 to 10 days, with a range of 5 to 21 days.</p><small class='source'>Printed p. 667 · PDF p. 681</small></section><section><h2>Diagnostic Tests</h2><p>Culture previously was considered the gold standard for laboratory diagnosis of pertussis but is not optimally sensitive and has largely been replaced by nucleic acid amplification tests (NAATs). Culture requires collection of an appropriate nasopharyngeal swab specimen, obtained either by aspiration or with polyester or flocked rayon swabs. Specimens must not be allowed to dry during prompt transport to the laboratory. Culture results can be negative if obtained from a previously immunized person, if antimicrobial therapy has been started, if more than 2 weeks has elapsed since cough onset, or if the specimen is not collected or handled appropriately. Testing nasopharyngeal swab specimens by rolling on slides and staining with direct fluorescent antibodies is not recommended because of nonspecific cross-reactions.</p><small class='source'>Printed p. 667 · PDF p. 681</small><p>NAATs cleared by the U.S. Food and Drug Administration (FDA), including polymerase chain reaction (PCR) assays, are commercially available as stand-alone tests or as multiplex assays and are the most commonly used laboratory method for detection of B pertussis because of greater sensitivity and more rapid turnaround time. The PCR test requires collection of an adequate nasopharyngeal specimen using a polyester or flocked swab or nasopharyngeal wash or aspirate. Calcium alginate swabs can be inhibitory to PCR and should not be used. The PCR test has optimal sensitivity during the first 3 weeks of cough and is unlikely to be useful if a patient has been receiving antimicrobial therapy for more than 5 days. The Centers for Disease Control and Prevention (CDC) has released a “best practices” document to guide pertussis PCR assays (www.cdc.gov/pertussis/ clinical/diagnostic-testing/diagnosis-pcrbestpractices.html) as well as a video demonstrating optimal specimen collection. Most PCR assays target a multicopy insertion gene sequence (IS481) found in B pertussis as well as the less commonly encountered B holmesii and some strains of B bronchiseptica. Several multiplex PCR assays test for both B pertussis and B parapertussis utilizing differing DNA targets for each pathogen. Multiple DNA target sequences are required to distinguish among clinically relevant Bordetella species.</p><small class='source'>Printed p. 668 · PDF p. 682</small><p>Serologic tests for pertussis infection may be helpful for diagnosis, especially late in illness, but are not commonly used. The CDC and FDA have developed a pertussis serologic test that has been used by state public health laboratories during outbreaks; however, no commercial kit is cleared by the FDA for diagnostic use. In the absence of recent immunization, an elevated serum immunoglobulin (Ig) G antibody to pertussis toxin (PT) present 2 to 8 weeks after onset of cough is suggestive of recent B pertussis infection. For single serum specimens, an IgG anti-PT value of approximately 100 IU/mL or greater (using an assay calibrated to standard reference sera) has been recommended. IgA and IgM assays lack adequate sensitivity and specificity and should not be used for the diagnosis of pertussis.</p><small class='source'>Printed p. 668 · PDF p. 682</small><p>An increased white blood cell count attributable to absolute lymphocytosis is suggestive of pertussis in infants and young children but often is absent in older people with pertussis and may be only mildly abnormal in some infants. A markedly elevated white blood cell count is associated with a poor prognosis in young infants.</p><small class='source'>Printed p. 668 · PDF p. 682</small></section><section><h2>Treatment</h2><p>Antimicrobial therapy administered during the catarrhal stage may ameliorate the disease. Antimicrobial therapy is indicated before test results are received if the clinical history is strongly suggestive of pertussis or the patient is at high risk of severe or complicated disease (eg, an infant). A 5-day course of azithromycin is the appropriate first-line choice for treatment and for postexposure prophylaxis (PEP [see Table 109.1]). After the paroxysmal cough is established, antimicrobial agents have no discernible effect on the course of illness but are recommended to limit spread of organisms to others. Resistance of B pertussis to macrolide antimicrobial agents has been reported but rarely in the United States. Penicillins and cephalosporins are not effective against B pertussis. Trimethoprimsulfamethoxazole is an alternative for patients older than 2 months who cannot tolerate macrolides or who are infected with a macrolideresistant strain, but studies evaluating trimethoprim-sulfamethoxazole as treatment for pertussis are limited. When administered in the first 6 weeks of life, oral erythromycin and, to a lesser degree azithromycin, are associated with increased risk of infantile hypertrophic pyloric stenosis, but azithromycin remains the drug of choice for treatment or prophylaxis of pertussis in very young infants.</p><small class='source'>Printed p. 668 · PDF p. 682</small><p>Young infants are at increased risk of respiratory failure attributable to apnea or secondary bacterial pneumonia and are at risk of cardiopulmonary failure and death from severe pulmonary hypertension. Hospitalization is most common in infants younger than 6 months. Characteristics that would suggest the need for hospitalization of infants with pertussis include young age, respiratory distress, inability to feed, cyanosis or apnea, and seizures. Hospitalized young infants with pertussis should be managed in a setting/facility where these complications can be recognized and managed urgently. Exchange transfusions or leukopheresis have been reported to be lifesaving in infants with progressive pulmonary hypertension and markedly elevated lymphocyte counts.</p><small class='source'>Printed p. 668 · PDF p. 682</small><p>Because data on the clinical effectiveness of antibiotic treatment on B parapertussis are limited, treatment decisions should be based on clinical judgment, with particular attention to special populations that may be at increased risk for severe B parapertussis disease, including infants, elderly people, and immunocompromised people. Limited available data suggest that B parapertussis is less susceptible to antimicrobial agents than B pertussis, although some studies indicate that macrolides, trimethoprim-sulfamethoxazole, and ciprofloxacin generally have activity against B parapertussis. B bronchiseptica has intrinsic resistance to macrolide antibiotics.</p><small class='source'>Printed p. 669 · PDF p. 683</small></section><section><h2>Infection Prevention And Control Measures In Health Care Settings</h2><p>In addition to standard precautions, droplet precautions are recommended for 21 days from onset of cough if appropriate antimicrobial therapy is not administered or for 5 days after initiation of effective therapy.</p><small class='source'>Printed p. 669 · PDF p. 683</small></section><section><h2>Control Measures</h2><p>Care of Exposed People Individuals, regardless of immunization status and in all settings, who have been in close contact with a person infected with pertussis should be monitored closely for respiratory tract symptoms for 21 days after last contact with the infected person. Close contacts with cough should be evaluated. People in child care settings (both workers and children), schools (both teachers and students), and health care settings with confirmed pertussis should be excluded from child care, school, or work until completion of 5 days of the recommended course of antimicrobial therapy. Untreated individuals should be excluded until 21 days have elapsed from cough onset.</p><small class='source'>Printed p. 669 · PDF p. 683</small><p>Household and Other Close Contacts PEP is recommended for all household contacts of the index case and other close contacts, including children in child care, regardless of immunization status (www.cdc.gov/pertussis/pep.html). When considering a nonhousehold contact with an uncertain amount of exposure, PEP should be administered if the contact personally is at high risk or will have close contact with a person at high risk of severe pertussis (eg, young infant, pregnant person, person who has contact with infants). If 21 days have elapsed since onset of cough in the index case, PEP has limited value but may be considered for households or in situations with high-risk contacts. The agents, doses, and duration of PEP are the same as for treatment of pertussis (see Table 109.1). Prophylaxis for people exposed to B parapertussis is not recommended.</p><small class='source'>Printed p. 670 · PDF p. 684</small><p>Close contacts who are unimmunized or underimmunized should have pertussis immunization initiated or continued as soon as possible using age-appropriate products according to the recommended schedule; this includes off-label use of tetanus toxoid, reduced-content diphtheria toxoid, and acellular pertussis vaccine (Tdap) in children 7 through 9 years of age who did not complete the diphtheria and tetanus toxoids and acellular pertussis vaccine (DTaP) series (see Table 109.2).</p><small class='source'>Printed p. 670 · PDF p. 684</small><p>Because pertussis-containing vaccines are non-live, they can be administered concomitantly with PEP.</p><small class='source'>Printed p. 671 · PDF p. 685</small><p>Child Care Pertussis vaccine and PEP should be administered as recommended for household and other close contacts. In the setting of known pertussis exposure, children and child care providers who are symptomatic should be excluded from the child care setting, pending evaluation by a physician.</p><small class='source'>Printed p. 671 · PDF p. 685</small><p>Schools Use of PEP for large groups of students usually is not recommended, especially in the setting of widespread community transmission, but exceptions for specific individuals can be considered. This occurs when close contact simulates household exposure or when pertussis in the exposed person may result in severe medical consequences. Public health officials should be consulted for recommendations to control pertussis transmission in schools. The immunization status of close contacts should be reviewed, and appropriate vaccines administered when indicated. Parents and teachers should be notified about possible exposures to pertussis. Exclusion of exposed people with cough illness within 21 days of last exposure should be considered pending evaluation by a physician.</p><small class='source'>Printed p. 671 · PDF p. 685</small><p>Health Care Settings1 Health care facilities should maximize efforts to immunize all health care personnel (HCP) with Tdap. All HCP should observe droplet precautions when examining a patient with pertussis (see Infection Prevention and Control Measures in Health Care Settings). People exposed to a patient with pertussis should be evaluated by infection control personnel for postexposure management and follow-up.</p><small class='source'>Printed p. 671 · PDF p. 685</small><p>Recommendations of the CDC are as follows:</p><small class='source'>Printed p. 671 · PDF p. 685</small><p>• PEP is recommended for all HCP (even if immunized with Tdap) who have been exposed to pertussis and are likely to expose patients at risk of severe pertussis (eg, hospitalized neonates and pregnant women). Other exposed HCP either should receive PEP or should be monitored daily for 21 days after exposure and treated at the onset of signs and symptoms of pertussis.</p><small class='source'>Printed p. 671 · PDF p. 685</small><p>• Other people (patients, caregivers) defined as close contacts or high-risk contacts of a patient or HCP with pertussis should receive PEP (and immunization when indicated), as recommended for household contacts (see Table 109.1).</p><small class='source'>Printed p. 671 · PDF p. 685</small><p>• HCP with symptoms of pertussis (or HCP with any respiratory illness within 21 days of exposure to pertussis who did not receive PEP) should be excluded from work for at least the first 5 days of the recommended antimicrobial therapy. HCP with symptoms of pertussis who do not accept antimicrobial therapy should be excluded from work for 21 days from onset of cough.</p><small class='source'>Printed p. 671 · PDF p. 685</small><p>Immunization Vaccine Products Acellular-component pertussis vaccines (DTaP) replaced previously used diphtheria, tetanus, and whole-cell pertussis vaccine (DTwP or DTP) exclusively in 1997; see Table 109.2 for products. All pertussis vaccines in the United States are combined with diphtheria and tetanus toxoids; none contains thimerosal as a preservative. DTaP products may be formulated as combination vaccines that contain other vaccine components. Adolescent and adult formulations, known as Tdap vaccines, contain reduced quantities of diphtheria toxoid and some pertussis antigens compared with DTaP.</p><small class='source'>Printed p. 671 · PDF p. 685</small><p>Dose and Route Each 0.5-mL dose of DTaP or Tdap is administered intramuscularly. Use of a decreased volume of individual doses of pertussis vaccines or multiple doses of decreased-volume (fractional) doses is not recommended.</p><small class='source'>Printed p. 671 · PDF p. 685</small><p>Interchangeability of Acellular Pertussis Vaccines Insufficient data exist on the safety, immunogenicity, and effectiveness of DTaP vaccines from different manufacturers when administered interchangeably for the primary series in infants. In circumstances in which the type of DTaP product(s) received previously is unknown or the previously administered product(s) is not readily available, any DTaP vaccine licensed for use in the primary series may be used. There is no need to match Tdap vaccine manufacturer with DTaP vaccine manufacturer used for earlier doses.</p><small class='source'>Printed p. 671 · PDF p. 685</small><p>Recommendations for Routine Childhood Immunization With DTaP Five doses of pertussis-containing vaccine are recommended prior to entering school. The first dose of DTaP may be administered as early as 6 weeks of age, followed by 2 additional doses at intervals of approximately 2 months. The fourth dose of DTaP is recommended at 15 through 18 months of age, and the fifth dose of DTaP is administered at 4 through 6 years of age. The fourth dose can be administered as early as 12 months of age, provided 6 months have elapsed since the third dose was administered. If the fourth dose of pertussis vaccine is delayed until after the fourth birthday, the fifth dose is not recommended.</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>Other recommendations are as follows:</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>• Simultaneous administration of DTaP and all other recommended vaccines is acceptable. Vaccines should not be mixed in the same syringe unless the specific combination is licensed by the FDA.</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>• Inadvertent administration of Tdap instead of DTaP to a child younger than 7 years as dose 1, 2, or 3 of the DTaP series does not count as a valid dose; DTaP should be administered as soon as is feasible.</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>• Inadvertent administration of Tdap instead of DTaP to a child younger than 7 years of age as either dose 4 or 5 can be counted as valid for DTaP dose 4 or 5.</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>• During a pertussis outbreak in the community, public health authorities may recommend starting DTaP immunization as early as 6 weeks of age, with doses 2 and 3 in the primary series administered at intervals as short as 4 weeks.</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>• Children younger than 7 years who have begun but not completed their primary immunization schedule with DTwP outside the United States should receive DTaP to complete the pertussis immunization schedule.</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>• DTaP is not licensed or recommended for people 7 years or older.</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>Combined Vaccines Several pertussis-containing combination vaccines are licensed for use (see Table 109.2) and may be used when feasible and when any components are indicated and none is contraindicated.</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>Recommendations for Scheduling Pertussis Immunization for Children Younger Than 7 Years in Special Circumstances • For children who have received fewer than the recommended number of doses of pertussis vaccine but who have received the recommended number of diphtheria and tetanus toxoid vaccine doses for their age, DTaP should be administered to complete the recommended pertussis immunization schedule.</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>• The total number of doses of diphtheria and tetanus toxoids (as DTaP or DTwP) should not exceed 6 before the seventh birthday.</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>• Although B pertussis infection confers protection against recurrent infection, the duration of protection is unknown. Age-appropriate DTaP dose(s) or a Tdap dose should be administered to complete the standard or catch-up immunization series on schedule in people who have had pertussis infection. No minimum interval between disease and immunization is needed.</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>Adverse Events After DTaP Immunization in Children Younger Than 7 Years • Local and febrile reactions. Reactions to DTaP can occur within several hours of immunization and subside spontaneously within 48 hours without sequelae. Most commonly, these include redness, swelling, induration, and tenderness at the injection site as well as drowsiness and irritability. Less common reactions include anorexia, vomiting, crying, and slight to moderate fever.</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>• Limb swelling involving the entire thigh or upper arm has been reported in 2% to 3% of vaccine recipients after administration of the fourth and fifth doses of DTaP in that extremity. Although thigh swelling may interfere with walking, most children have no limitation of activity; the condition resolves spontaneously and has no sequelae. Entire limb swelling is not a contraindication to further DTaP, Tdap, or Td immunization.</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>• A review by the National Academy of Medicine based on case-series reports found evidence of a rare yet likely causal relationship between receipt of tetanus toxoid–containing vaccines and brachial neuritis. However, the frequency of this event has not been determined.</p><small class='source'>Printed p. 672 · PDF p. 686</small><p>• Seizures. In contrast to DTwP, no increased risk of seizures has been observed after DTaP administration. A small increased risk for febrile seizures after DTaP when administered simultaneously with inactivated (non-live) influenza vaccine was observed in a study by the CDC Vaccine Safety Datalink project. However, neither the CDC Advisory Committee on Immunization Practices (ACIP) nor the American Academy of Pediatrics recommends administering vaccines on separate days.</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>• Hypotonic-hyporesponsive episode.</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>Hypotonic-hyporesponsive episodes (also termed “collapse” or “shock-like state”) occur significantly less often after immunization with DTaP than previously shown with DTwP and are not a contraindication to subsequent dose(s).</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>• Other reactions. Severe anaphylactic reactions are rare after pertussis immunization. Transient urticarial rashes that occur occasionally after pertussis immunization, unless appearing immediately (ie, within minutes), are unlikely to be anaphylactic (IgE- mediated) in origin.</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>Contraindications and Precautions to DTaP Immunization Contraindications to DTaP and Tdap occur only very rarely, and in questioning about them, providers should probe whether a true contraindication actually exists. DTaP and Tdap contraindications are limited to only the following:</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>• Severe allergic reaction (eg, anaphylaxis) to a dose of DTaP or Tdap or to a vaccine component (Td) is a contraindication to DTaP, Tdap, or Td. Because of the importance of tetanus vaccination, people who experience anaphylactic reactions should be referred to an allergist to determine whether they have a specific allergy to tetanus toxoid and can be desensitized to tetanus toxoid.</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>• Encephalopathy (eg, coma, decreased level of consciousness, or prolonged seizures) not attributable to another identifiable cause within 7 days after administration of a previous dose of diphtheria and tetanus toxoids and pertussis vaccine (DTwP, DTaP, or Tdap) is a contraindication to the pertussis component.</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>Precautions to DTaP and Tdap:</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>• Guillain-Barré syndrome within 6 weeks after a previous dose of tetanus toxoid– containing vaccine is a precaution to further doses of DTaP, Tdap, or Td.</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>• Moderate or severe acute illness with or without a fever is a reason to defer administration of any vaccine until the person has recovered.</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>• Evolving neurologic disorder generally is a reason to defer DTaP or Tdap immunization temporarily to reduce confusion about reason(s) for a change in the clinical course. Note that as of 2023 DT is no longer available in the United States (www.cdc.gov/vaccines/ vpd/dtap-tdap-td/hcp/recommendations. html and www.cdc.gov/vaccines/vpd/ dtap-tdap-td/hcp/td-offlabel.html). For young children with a contraindication to pertussis-containing vaccines, vaccine providers may administer Td for all recommended remaining doses in place of DTaP. Td contains a lower dose (approximately 1/12th the amount) of diphtheria toxoid compared with DT. The impact of this lower dose on the protection provided against diphtheria in young children is uncertain. Available evidence suggests young children who receive Td in place of DTaP may have suboptimal protection against diphtheria.</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>Recommendations for Routine Adolescent Immunization With Tdap2,3 Adolescents 11 years and older should receive a single dose of Tdap instead of Td for booster immunization against tetanus, diphtheria, and pertussis. The preferred age for Tdap immunizations is 11 through 12 years of age.</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>• Adolescents who received Td but not Tdap should receive a single dose of Tdap to provide protection against pertussis regardless of time since receipt of Td.</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>• Simultaneous administration of Tdap and all other recommended vaccines is recommended when feasible.</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>• Inadvertent administration of DTaP instead of Tdap in people 7 years and older is counted as a valid dose of Tdap.</p><small class='source'>Printed p. 673 · PDF p. 687</small><p>Recommendations for Scheduling Tdap in Children 7 Years and Older Who Did Not Complete Recommended DTaP Doses Before 7 Years of Age4 • Children 7 through 10 years of age who have not completed their immunization schedule with DTaP before 7 years of age or who have an unknown vaccine history should receive at least 1 dose of Tdap. If further dose(s) of tetanus and diphtheria toxoids are needed in a catch-up schedule, either Td or Tdap can be used. The preferred schedule is Tdap followed by Td or Tdap at 2 months and 6 to 12 months (if needed).</p><small class='source'>Printed p. 674 · PDF p. 688</small><p>• Children 7 through 9 years of age who receive Tdap or DTaP for any reason should receive the adolescent Tdap booster at 11 through 12 years of age.</p><small class='source'>Printed p. 674 · PDF p. 688</small><p>• A Tdap or DTaP dose received by a 10-year-old for any reason can count as the adolescent Tdap booster dose.</p><small class='source'>Printed p. 674 · PDF p. 688</small><p>Recommendations for Adolescent and Adult Immunization With Tdap in Special Situations5 Despite the burden of pertussis in the community, a decision analysis conducted by the CDC concluded that a routine second dose would have a limited effect on overall disease rates. However, repeat doses of Tdap are generally well tolerated, and either Td or a Tdap can be used regardless of prior receipt of Tdap for catch-up immunization of individuals 7 years and older, for the routine decennial tetanus-diphtheria booster, and for wound prophylaxis when indicated. Special situations for use of Tdap, or repeated use of Tdap offlabel, are provided in the following sections.</p><small class='source'>Printed p. 674 · PDF p. 688</small><p>Use of Tdap in Pregnancy6 Tdap is approved by the FDA for use in the third trimester of pregnancy to prevent pertussis in infants younger than 2 months of age. In order to protect infants, who have a high risk for severe or fatal pertussis, the ACIP recommends that a dose of Tdap be administered during each pregnancy, irrespective of the pregnant individual’s prior history of receiving Tdap or having had pertussis. Immunization during pregnancy leads to transplacental transfer of antibody that has been shown to provide protection to the infant. Tdap may be administered at any time during pregnancy, but current evidence suggests that immunization early in the interval between 27 and 36 weeks of gestation will maximize passive antibody transfer to the infant. For people not previously vaccinated with Tdap and in whom Tdap was not administered during pregnancy for some reason, Tdap should be administered immediately postpartum. Postpartum Tdap is not recommended for people who have received a previous Tdap dose unless they are due for their decennial tetanus booster.</p><small class='source'>Printed p. 674 · PDF p. 688</small><p>Protection of Young Infants: The Cocoon Strategy Tdap vaccination during each pregnancy is the preferred strategy for protecting young infants from pertussis in the early months of life. In addition, the American Academy of Pediatrics, CDC, American College of Obstetricians and Gynecologists, American Academy of Family Physicians, American College of Nurse-Midwives, American Academy of Physician Associates, and National Association of Pediatric Nurse Practitioners recommend the “cocoon” strategy to help protect infants from pertussis by immunizing those around them. This strategy may offer indirect protection by decreasing their likelihood of acquisition and subsequent development of clinical pertussis. Immunizing parents or other adult family contacts in the pediatric office setting could increase immunization coverage for this population.7 • Underimmunized children younger than 7 years should receive DTaP, and underimmunized children 7 years and older should receive Tdap (see previous discussion).</p><small class='source'>Printed p. 674 · PDF p. 688</small><p>• All adolescents and adults should have received a single dose of Tdap, ideally at least 2 weeks before beginning close contact with the infant. There is no minimum interval required between Tdap and prior Td.</p><small class='source'>Printed p. 674 · PDF p. 688</small><p>• Cough illness in contacts of neonates should be investigated and managed promptly, with consideration given for azithromycin prophylaxis for the neonate if pertussis contact is likely (see Control Measures).</p><small class='source'>Printed p. 674 · PDF p. 688</small><p>Special Situations • Wound management.8 A tetanus toxoid– containing vaccine is indicated for wound management when &gt;5 years have passed since the last tetanus toxoid–containing vaccine dose. If a tetanus toxoid–containing vaccine is indicated for persons aged 11 years, Tdap is preferred for persons who have not previously received Tdap or whose Tdap history is unknown. If a tetanus toxoid–containing vaccine is indicated for a pregnant person, Tdap should be used. For nonpregnant persons with documentation of previous Tdap vaccination, either Td or Tdap may be used if a tetanus toxoid–containing vaccine is indicated.</p><small class='source'>Printed p. 674 · PDF p. 688</small><p>• Pregnant people for whom tetanus booster is due. If Td booster immunization is indicated during pregnancy (ie, 10 years or more since previous Td), Tdap should be administered, preferably early in the interval between weeks 27 and 36 of gestation.</p><small class='source'>Printed p. 675 · PDF p. 689</small><p>• Pregnant people with unknown or incomplete tetanus vaccination. To ensure protection against maternal and neonatal tetanus, pregnant people who never have been immunized against tetanus should receive 3 doses of Td-containing vaccines during pregnancy. The recommended schedule is 0, 4 weeks, and 6 to 12 months, and at least 1 Tdap dose should be used in this series, preferably early in the interval between 27 and 36 weeks of gestation; either Td or Tdap can be used to complete the series.</p><small class='source'>Printed p. 675 · PDF p. 689</small><p>Health Care Professionals The CDC recommends a single dose of Tdap as soon as is feasible for HCP of any age who previously have not received Tdap. There is no minimum interval suggested or required between Tdap and prior Td.</p><small class='source'>Printed p. 675 · PDF p. 689</small><p>In certain cases (eg, documented transmission in the health care setting), revaccination of HCP with Tdap may be considered (www.cdc.gov/vaccines/ vpd/pertussis/tdap-revac-hcp.html). In such a case, Tdap is not a substitute for infection prevention and control measures, including PEP for exposed HCP. If implemented, HCP who work with infants or pregnant people should be prioritized for revaccination.</p><small class='source'>Printed p. 675 · PDF p. 689</small><p>Hospitals and ambulatory care facilities should provide Tdap for HCP and maximize immunization rates (eg, education about the benefits of immunization or mandatory requirement, convenient access, and provision of Tdap at no charge).</p><small class='source'>Printed p. 675 · PDF p. 689</small><p>Recommendations for Adult Immunization With Tdap The CDC recommends administration of a single dose of Tdap universally for adults of any age who previously have not received Tdap, with no minimum interval required between Tdap and prior dose of Td.</p><small class='source'>Printed p. 675 · PDF p. 689</small><p>Adverse Events After Administration of Tdap Local adverse events after administration of Tdap in adolescents and adults are common but usually are mild. Systemic adverse events also are common but usually are mild (eg, any fever, 3%–14%; any headache, 40%–44%; tiredness, 27%–37%). Postmarketing data suggest that these events occur at approximately the same rate and severity as following receipt of Td.</p><small class='source'>Printed p. 675 · PDF p. 689</small><p>Contraindications, Precautions, and Deferral of Use of Tdap in Adolescents and Adults Anaphylaxis that occurred after any component of the vaccine is a contraindication to Tdap. In individuals with latex allergy, package inserts should be consulted regarding latex content.</p><small class='source'>Printed p. 675 · PDF p. 689</small><p>History of Guillain-Barré syndrome within 6 weeks of a dose of a tetanus toxoid vaccine is a precaution to Tdap immunization. If the decision is made to continue tetanus toxoid immunization, Tdap is preferred if indicated. A history of severe Arthus hypersensitivity reaction after a previous dose of a tetanus or diphtheria toxoid– containing vaccine administered less than 10 years previously should lead to deferral of Tdap or Td immunization for 10 years after administration of the tetanus or diphtheria toxoid–containing vaccine.</p><small class='source'>Printed p. 675 · PDF p. 689</small><p>Public Health Reporting Pertussis is a nationally notifiable disease in the United States.</p><small class='source'>Printed p. 675 · PDF p. 689</small></section><h2>Original tables</h2><figure><img loading='lazy' src='tables/ch109_p0683_1.jpg' alt='Original table on printed page 669'><figcaption>Original table · printed p. 669</figcaption></figure><figure><img loading='lazy' src='tables/ch109_p0684_1.jpg' alt='Original table on printed page 670'><figcaption>Original table · printed p. 670</figcaption></figure><h2>Visual atlas</h2><figure><a href='figures/ch109_p0690_01.jpg' target='_blank'><img loading='lazy' src='figures/ch109_p0690_01.jpg' alt='Image 109.1 A preschool-aged boy with pertussis. Thick respiratory secretions were produced by a paroxysmal coughing spell. Courtesy of Edgar O. Ledbetter, MD, FAAP.'></a><figcaption>Image 109.1 A preschool-aged boy with pertussis. Thick respiratory secretions were produced by a paroxysmal coughing spell. Courtesy of Edgar O. Ledbetter, MD, FAAP.<br><small>Printed p. 676 · PDF p. 690</small></figcaption></figure><figure><a href='figures/ch109_p0690_02.jpg' target='_blank'><img loading='lazy' src='figures/ch109_p0690_02.jpg' alt='Image 109.2 Bilateral subconjunctival hemorrhages and thick nasal mucus in an infant with pertussis.'></a><figcaption>Image 109.2 Bilateral subconjunctival hemorrhages and thick nasal mucus in an infant with pertussis.<br><small>Printed p. 676 · PDF p. 690</small></figcaption></figure><figure><a href='figures/ch109_p0690_03.jpg' target='_blank'><img loading='lazy' src='figures/ch109_p0690_03.jpg' alt='Image 109.3 Radiographs obtained in a 4-week-old with pertussis pneumonia with pulmonary air trapping and progressive atelectasis confirmed at autopsy. The neonate acquired the infection from the mother shortly after birth. Segmented and lobar atelectasis are not uncommon complications of pertussis.'></a><figcaption>Image 109.3 Radiographs obtained in a 4-week-old with pertussis pneumonia with pulmonary air trapping and progressive atelectasis confirmed at autopsy. The neonate acquired the infection from the mother shortly after birth. Segmented and lobar atelectasis are not uncommon complications of pertussis.<br><small>Printed p. 676 · PDF p. 690</small></figcaption></figure><figure><a href='figures/ch109_p0691_01.jpg' target='_blank'><img loading='lazy' src='figures/ch109_p0691_01.jpg' alt='Image 109.5 Plugging and alveolar dilatation of pertussis pneumonia in an infant who died. Courtesy of Edgar O. Ledbetter, MD, FAAP.'></a><figcaption>Image 109.5 Plugging and alveolar dilatation of pertussis pneumonia in an infant who died. Courtesy of Edgar O. Ledbetter, MD, FAAP.<br><small>Printed p. 677 · PDF p. 691</small></figcaption></figure><figure><a href='figures/ch109_p0691_02.jpg' target='_blank'><img loading='lazy' src='figures/ch109_p0691_02.jpg' alt='Image 109.6 Pertussis pneumonia with hyperaeration (air trapping) caused by inability to cough out thick pulmonary secretions.'></a><figcaption>Image 109.6 Pertussis pneumonia with hyperaeration (air trapping) caused by inability to cough out thick pulmonary secretions.<br><small>Printed p. 677 · PDF p. 691</small></figcaption></figure><figure><a href='figures/ch109_p0691_03.jpg' target='_blank'><img loading='lazy' src='figures/ch109_p0691_03.jpg' alt='Image 109.7 Pertussis pneumonia in a 7-year-old who was exhausted from persistent coughing. Obliteration of cardiac borders on the chest radiograph is a common radiographic change of pertussis pneumonia.'></a><figcaption>Image 109.7 Pertussis pneumonia in a 7-year-old who was exhausted from persistent coughing. Obliteration of cardiac borders on the chest radiograph is a common radiographic change of pertussis pneumonia.<br><small>Printed p. 677 · PDF p. 691</small></figcaption></figure><figure><a href='figures/ch109_p0691_04.jpg' target='_blank'><img loading='lazy' src='figures/ch109_p0691_04.jpg' alt='Image 109.4 Bronchiolar plugging in the neonate in Image 109.3, who died of pertussis pneumonia. Neonates, infants, and children often acquire pertussis from an infected adult or sibling contact.'></a><figcaption>Image 109.4 Bronchiolar plugging in the neonate in Image 109.3, who died of pertussis pneumonia. Neonates, infants, and children often acquire pertussis from an infected adult or sibling contact.<br><small>Printed p. 677 · PDF p. 691</small></figcaption></figure><figure><a href='figures/ch109_p0692_01.jpg' target='_blank'><img loading='lazy' src='figures/ch109_p0692_01.jpg' alt='Image 109.8 This image depicts an infant girl who presented to a clinic with malnutrition as well as what was diagnosed as pertussis. Pertussis is a highly communicable, vaccinepreventable disease caused by Bordetella pertussis, a gram-negative coccobacillus, that lasts for many weeks and typically affects children with severe coughing, whooping, and post-tussive vomiting. Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 109.8 This image depicts an infant girl who presented to a clinic with malnutrition as well as what was diagnosed as pertussis. Pertussis is a highly communicable, vaccinepreventable disease caused by Bordetella pertussis, a gram-negative coccobacillus, that lasts for many weeks and typically affects children with severe coughing, whooping, and post-tussive vomiting. Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 678 · PDF p. 692</small></figcaption></figure><figure><a href='figures/ch109_p0692_02.jpg' target='_blank'><img loading='lazy' src='figures/ch109_p0692_02.jpg' alt='Image 109.9 This child has pertussis (whooping cough). He has severe coughing spasms, which are often followed by a whooping sound. It is difficult for him to stop coughing and catch his breath. Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 109.9 This child has pertussis (whooping cough). He has severe coughing spasms, which are often followed by a whooping sound. It is difficult for him to stop coughing and catch his breath. Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 678 · PDF p. 692</small></figcaption></figure><figure><a href='figures/ch109_p0692_03.jpg' target='_blank'><img loading='lazy' src='figures/ch109_p0692_03.jpg' alt='Image 109.11 Colonies of Bordetella pertussis growing on Bordet-Gengou media. Courtesy of Edgar O. Ledbetter, MD, FAAP.'></a><figcaption>Image 109.11 Colonies of Bordetella pertussis growing on Bordet-Gengou media. Courtesy of Edgar O. Ledbetter, MD, FAAP.<br><small>Printed p. 678 · PDF p. 692</small></figcaption></figure><figure><a href='figures/ch109_p0692_04.jpg' target='_blank'><img loading='lazy' src='figures/ch109_p0692_04.jpg' alt='Image 109.10 This child has broken blood vessels in his eyes and bruising on his face because of coughing from pertussis. Courtesy of Thomas Schlenker, MD, MPH, chief medical officer, Children’s Hospital of Wisconsin.'></a><figcaption>Image 109.10 This child has broken blood vessels in his eyes and bruising on his face because of coughing from pertussis. Courtesy of Thomas Schlenker, MD, MPH, chief medical officer, Children’s Hospital of Wisconsin.<br><small>Printed p. 678 · PDF p. 692</small></figcaption></figure>"});
